($$estevao-martir$$, $$Santo Estêvão$$, $$Primeiro Mártir$$, $$26 de Dezembro$$, 12, 26, $$Séc. I, Jerusalém$$, $$34, Jerusalém$$, '{"Diáconos","Pedreiros"}'::text[], $$Um dos sete primeiros diáconos da Igreja, martirizado por apedrejamento.$$, $$Um dos sete primeiros diáconos da Igreja, martirizado por apedrejamento.$$, $$[]$$::jsonb, '{"\"Senhor Jesus, recebe o meu espírito.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Fra_Angelico_013.jpg/440px-Fra_Angelico_013.jpg$$, NULL, '{"Coragem","Perdão"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$joao-apostolo$$, $$São João Evangelista$$, $$O Discípulo Amado$$, $$27 de Dezembro$$, 12, 27, $$Séc. I, Galileia$$, $$100, Éfeso$$, '{"Teólogos","Escritores"}'::text[], $$Autor do quarto Evangelho, das Epístolas e do Apocalipse. O único apóstolo que não foi martirizado.$$, $$Autor do quarto Evangelho, das Epístolas e do Apocalipse. O único apóstolo que não foi martirizado.$$, $$[]$$::jsonb, '{"\"Deus é amor.\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Hans_Memling_-_Saint_John_the_Evangelist_-_WGA14819.jpg/440px-Hans_Memling_-_Saint_John_the_Evangelist_-_WGA14819.jpg$$, NULL, '{"Amor","Fidelidade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
